<?php $page_title='My Profile'; require_once 'includes/header.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['name']??'');$bio=trim($_POST['bio']??'');$phone=trim($_POST['phone']??'');$city=trim($_POST['city']??'');$avatar=upload_image('avatar','avatars','avatar_');if(!$name)throw new RuntimeException('Name is required.');$sql='UPDATE users SET name=?,bio=?,phone=?,city=?'.($avatar?',avatar=?':'').' WHERE id=?';$args=[$name,$bio,$phone,$city];if($avatar)$args[]=$avatar;$args[]=user()['id'];$pdo->prepare($sql)->execute($args);$_SESSION['user']['name']=$name;flash('success','Profile updated successfully.');redirect('profile.php');}catch(Throwable $e){flash('error',$e->getMessage());}}
$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([user()['id']]);$me=$s->fetch();
?><section class="page-hero"><span class="kicker">YOUR IDENTITY</span><h1>Build your FIBIN profile.</h1><p>Add a photo, bio and city so community members know who they are talking to.</p></section><section class="profile-grid"><div class="profile-card profile-cover"><div class="avatar-xl"><?php if($me['avatar']):?><img src="<?=e($me['avatar'])?>" alt="Profile photo"><?php else:?><?=e(strtoupper(substr($me['name'],0,1)))?><?php endif;?></div><h2><?=e($me['name'])?></h2><span class="badge info">@<?=e($me['username'])?></span><p><?=e($me['bio']?:'FIBIN community member')?></p><div class="profile-meta"><span>📍 <?=e($me['city']?:'Location not set')?></span><span>🎯 <?=e(ucfirst($me['role']))?></span></div></div><div class="form-card"><h2>Edit profile</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name<input name="name" value="<?=e($me['name'])?>" required></label><label>Profile photo<input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></label><label>Phone<input name="phone" value="<?=e($me['phone'])?>" placeholder="Optional"></label><label>City / area<input name="city" value="<?=e($me['city'])?>" placeholder="Faridabad"></label><label>Bio<textarea name="bio" rows="5" placeholder="Tell the community about yourself..."><?=e($me['bio'])?></textarea></label><button class="btn primary full-btn">Save profile</button></form></div></section><?php require_once 'includes/footer.php'; ?>
